item.command:
/bin/bash -lc "python - <<'PY'
import urllib.request,gzip,json,collections
u='https://storage.googleapis.com/gcp-public-data--gnomad/release/3.1.2/vcf/genomes/gnomad.genomes.v3.1.2.hgdp_1kg_subset_sample_meta.tsv.bgz'
text=gzip.decompress(urllib.request.urlopen(u, timeout=60).read()).decode()
cols=text.splitlines()[0].split('\\t')
for col in ['gnomad_population_inference','hgdp_tgp_meta']:
    idx=cols.index(col); vals=collections.defaultdict(collections.Counter); keys=collections.Counter()
    for line in text.splitlines()[1:]:
